// Recuperer les chunks retournes par le Vector Store (top 15)
const retrievedChunks = $input.all();

// Recuperer les donnees du formulaire via reference cross-node
const formData = $('On form submission').item.json;

// Extraire le framework choisi par l'utilisateur
const targetFramework = formData["Framework reglementaire"];

// FILTRAGE METADATA : ne garder que les chunks du framework cible
// NOTE : structure reelle = item.json.document.metadata.framework
const filteredChunks = retrievedChunks.filter(item => 
  item.json.document && 
  item.json.document.metadata && 
  item.json.document.metadata.framework === targetFramework
);

// Garder les 8 plus pertinents apres filtrage
const top8Chunks = filteredChunks.slice(0, 8);

// Concatener les chunks en un contexte lisible pour l'agent
const retrievedContext = top8Chunks
  .map((item, idx) => {
    const meta = item.json.document.metadata;
    const content = item.json.document.pageContent;
    return `[CHUNK ${idx + 1} - ${meta.framework} Article ${meta.article_number} - ${meta.article_title}]\n\n${content}`;
  })
  .join('\n\n---\n\n');

// Diagnostic pour debugging
const diagnostics = {
  total_retrieved: retrievedChunks.length,
  total_after_framework_filter: filteredChunks.length,
  framework_targeted: targetFramework,
  chunks_used_for_context: top8Chunks.length,
  chunks_articles: top8Chunks.map(item => 
    `${item.json.document.metadata.framework} Art. ${item.json.document.metadata.article_number}`
  ),
  chunks_scores: top8Chunks.map(item => 
    item.json.score ? item.json.score.toFixed(4) : 'N/A'
  )
};

// Retourner contexte + donnees formulaire pour l'agent
return [{
  json: {
    // Donnees formulaire (passees telles quelles a l'agent)
    entity_name: formData["Nom de l'entite auditee"],
    framework: formData["Framework reglementaire"],
    article_number: formData["Numero d'article a auditer"],
    sector: formData["Secteur d'activite"],
    perimeter: formData["Perimetre teste"],
    entity_type: formData["Type d'entite"],

    // Contexte RAG filtre
    retrieved_context: retrievedContext,

    // Diagnostic
    diagnostics: diagnostics
  }
}];

