// Recuperer l'output de l'agent IA
const agentOutput = $input.first().json.output;

// Recuperer les donnees du formulaire pour les metadonnees de ligne
const formData = $('On form submission').item.json;
const contextData = $('Preparer contexte audit').item.json;

// Nettoyer l'output : enlever les eventuels backticks markdown autour du JSON
let cleanedOutput = agentOutput.trim();
if (cleanedOutput.startsWith('```json')) {
  cleanedOutput = cleanedOutput.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleanedOutput.startsWith('```')) {
  cleanedOutput = cleanedOutput.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

// Parser le JSON
let auditKit;
try {
  auditKit = JSON.parse(cleanedOutput);
} catch (e) {
  return [{
    json: {
      error: "Echec parsing JSON",
      details: e.message,
      raw_output: agentOutput.substring(0, 500)
    }
  }];
}

// Generer un identifiant unique d'audit
const auditId = `AUDIT-${formData["Framework reglementaire"]}-Art${formData["Numero d'article a auditer"]}-${Date.now()}`;
const now = new Date().toISOString();

// Construire UNE seule ligne synthetique pour Sheets (vue d'ensemble)
const summaryRow = {
  audit_id: auditId,
  date_generation: now,
  entite: auditKit.metadata.entite,
  framework: auditKit.metadata.framework,
  article: auditKit.metadata.article,
  secteur: formData["Secteur d'activite"],
  perimetre: auditKit.metadata.perimetre,
  type_entite: formData["Type d'entite"],
  nb_tests: auditKit.plan_test ? auditKit.plan_test.length : 0,
  nb_preuves: auditKit.preuves_a_collecter ? auditKit.preuves_a_collecter.length : 0,
  nb_questions: auditKit.trame_interview && auditKit.trame_interview.questions 
    ? auditKit.trame_interview.questions.length : 0,
  nb_findings: auditKit.findings_template ? auditKit.findings_template.length : 0,
  nb_mappings: auditKit.mapping_itil_cobit ? auditKit.mapping_itil_cobit.length : 0,
  interlocuteurs: auditKit.trame_interview && auditKit.trame_interview.interlocuteurs_cibles
    ? auditKit.trame_interview.interlocuteurs_cibles.join(' | ') : '',
  articles_couverts_rag: contextData.diagnostics.chunks_articles.join(' | '),
  kit_complet_json: JSON.stringify(auditKit, null, 2)
};

// Retourner UN seul item avec :
// - La ligne synthese pour Sheets
// - Le kit complet (pour l'email a venir)
return [{
  json: {
    audit_id: auditId,
    summary_row: summaryRow,
    audit_kit: auditKit,
    entity_name: formData["Nom de l'entite auditee"],
    framework: formData["Framework reglementaire"],
    article_number: formData["Numero d'article a auditer"]
  }
}];
